export const sampleReceipts = [
  {
    id: 1,
    name: 'Weekly Grocery Shopping',
    store: 'SuperMart',
    date: '2026-09-28',
    items: [
      { name: 'Milk (2L)', category: 'Dairy', price: 180, quantity: 2 },
      { name: 'Bread (Whole Wheat)', category: 'Bakery', price: 60, quantity: 3 },
      { name: 'Eggs (12 pcs)', category: 'Dairy', price: 240, quantity: 1 },
      { name: 'Chicken Breast (1kg)', category: 'Meat', price: 580, quantity: 2 },
      { name: 'Rice (5kg)', category: 'Grains', price: 650, quantity: 1 },
      { name: 'Tomatoes (1kg)', category: 'Vegetables', price: 80, quantity: 2 },
      { name: 'Onions (1kg)', category: 'Vegetables', price: 60, quantity: 2 },
      { name: 'Potatoes (2kg)', category: 'Vegetables', price: 90, quantity: 1 },
      { name: 'Apples (1kg)', category: 'Fruits', price: 320, quantity: 1 },
      { name: 'Bananas (1 dozen)', category: 'Fruits', price: 150, quantity: 1 },
      { name: 'Cooking Oil (1L)', category: 'Pantry', price: 280, quantity: 1 },
      { name: 'Salt (1kg)', category: 'Pantry', price: 35, quantity: 1 },
    ]
  },
  {
    id: 2,
    name: 'Monthly Essentials',
    store: 'MegaMart',
    date: '2026-09-25',
    items: [
      { name: 'Detergent Powder (2kg)', category: 'Household', price: 420, quantity: 1 },
      { name: 'Shampoo (500ml)', category: 'Personal Care', price: 380, quantity: 2 },
      { name: 'Toothpaste (200g)', category: 'Personal Care', price: 180, quantity: 3 },
      { name: 'Toilet Paper (12 rolls)', category: 'Household', price: 450, quantity: 1 },
      { name: 'Dish Soap (500ml)', category: 'Household', price: 120, quantity: 2 },
      { name: 'Coffee (200g)', category: 'Beverages', price: 580, quantity: 1 },
      { name: 'Tea (250g)', category: 'Beverages', price: 320, quantity: 1 },
      { name: 'Sugar (2kg)', category: 'Pantry', price: 180, quantity: 1 },
      { name: 'Flour (5kg)', category: 'Pantry', price: 520, quantity: 1 },
    ]
  },
  {
    id: 3,
    name: 'Quick Snacks & Beverages',
    store: 'QuickStop',
    date: '2026-09-30',
    items: [
      { name: 'Coca Cola (2L)', category: 'Beverages', price: 120, quantity: 2 },
      { name: 'Chips (Large)', category: 'Snacks', price: 95, quantity: 4 },
      { name: 'Chocolate Bar', category: 'Snacks', price: 65, quantity: 5 },
      { name: 'Juice (1L)', category: 'Beverages', price: 180, quantity: 2 },
      { name: 'Cookies (Pack)', category: 'Snacks', price: 120, quantity: 2 },
      { name: 'Ice Cream (1L)', category: 'Frozen', price: 380, quantity: 1 },
      { name: 'Yogurt (500g)', category: 'Dairy', price: 180, quantity: 3 },
    ]
  }
];

export const budgetCategories = [
  { name: 'Groceries', limit: 15000, color: 'rgb(34, 197, 94)' },
  { name: 'Household', limit: 5000, color: 'rgb(59, 130, 246)' },
  { name: 'Personal Care', limit: 3000, color: 'rgb(168, 85, 247)' },
  { name: 'Snacks & Beverages', limit: 2000, color: 'rgb(249, 115, 22)' },
];

export const spendingTrends = {
  labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4'],
  datasets: [
    {
      label: 'Weekly Spending',
      data: [3200, 4100, 3800, 4500],
      backgroundColor: 'rgba(59, 130, 246, 0.8)',
    },
    {
      label: 'Budget Limit',
      data: [5000, 5000, 5000, 5000],
      backgroundColor: 'rgba(239, 68, 68, 0.5)',
      type: 'line',
      borderColor: 'rgb(239, 68, 68)',
      borderWidth: 2,
    }
  ]
};

export const categoryBreakdown = (items) => {
  const categories = {};

  items.forEach(item => {
    if (!categories[item.category]) {
      categories[item.category] = 0;
    }
    categories[item.category] += item.price * item.quantity;
  });

  return {
    labels: Object.keys(categories),
    datasets: [{
      data: Object.values(categories),
      backgroundColor: [
        'rgba(34, 197, 94, 0.8)',
        'rgba(59, 130, 246, 0.8)',
        'rgba(168, 85, 247, 0.8)',
        'rgba(249, 115, 22, 0.8)',
        'rgba(236, 72, 153, 0.8)',
        'rgba(14, 165, 233, 0.8)',
        'rgba(234, 179, 8, 0.8)',
        'rgba(239, 68, 68, 0.8)',
      ]
    }]
  };
};
